import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"设置与通知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1788621106000}`),a={name:`guide/settings.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="设置与通知" tabindex="-1">设置与通知 <a class="header-anchor" href="#设置与通知" aria-label="Permalink to “设置与通知”">​</a></h1><h2 id="账号资料" tabindex="-1">账号资料 <a class="header-anchor" href="#账号资料" aria-label="Permalink to “账号资料”">​</a></h2><p>“管理 → 账号设置”显示用户名、绑定邮箱、OAuth 绑定、时区、用户等级和当前配额。时区会影响邮件时间、审计记录和自动回复时间窗口。</p><p>本地账号可以修改密码；OAuth 账号可绑定本地邮箱和密码作为备用登录方式。解绑 OAuth 前应确保仍有其他可用登录方式。</p><h2 id="邮件偏好" tabindex="-1">邮件偏好 <a class="header-anchor" href="#邮件偏好" aria-label="Permalink to “邮件偏好”">​</a></h2><p>邮件设置包括：</p><ul><li>标签与文件夹管理。</li><li>联系人和联系人访问控制。</li><li>全局签名及按发件邮箱选择的签名。</li><li>白名单与收信规则。</li><li>默认图床地址、个人图床 API Key 和上传策略。</li><li>全局自动回复及邮箱级覆盖。</li></ul><p>白名单会影响垃圾邮件判断，只添加可信地址或域名。图床密钥属于敏感凭据，不要粘贴到工单或公开页面。</p><h2 id="通知中心" tabindex="-1">通知中心 <a class="header-anchor" href="#通知中心" aria-label="Permalink to “通知中心”">​</a></h2><p>站内通知同时显示系统公告和账号相关事件，并提供未读数量与全部已读操作。管理员可按受众发布公告，个人事件可能来自订单、订阅、共享或其他业务流程。</p><p>浏览器通知需要浏览器授权。若点击测试没有弹窗，应检查浏览器站点权限、系统勿扰模式以及页面是否通过 HTTPS 打开。</p><h2 id="telegram-通知" tabindex="-1">Telegram 通知 <a class="header-anchor" href="#telegram-通知" aria-label="Permalink to “Telegram 通知”">​</a></h2><p>管理员配置机器人后，用户可从通知设置发起 Telegram 绑定。绑定采用 Telegram 官方网页登录授权；成功后可发送测试通知，也可随时解绑。</p><p>不要把普通 <code>/start</code> 当作账号绑定流程，也不要把机器人 Token 发给任何人。</p><h2 id="登录与审计记录" tabindex="-1">登录与审计记录 <a class="header-anchor" href="#登录与审计记录" aria-label="Permalink to “登录与审计记录”">​</a></h2><p>安全记录显示登录时间、来源和关键账号操作。发现未知登录时应立即修改密码、撤销应用专用密码、强制退出其他会话并联系管理员。</p><h2 id="客户端服务器" tabindex="-1">客户端服务器 <a class="header-anchor" href="#客户端服务器" aria-label="Permalink to “客户端服务器”">​</a></h2><p>第三方邮件客户端统一使用：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>服务器：mail.to9.us</span></span>
<span class="line"><span>IMAPS：993（SSL/TLS）</span></span>
<span class="line"><span>POP3S：995（SSL/TLS）</span></span>
<span class="line"><span>SMTP Submission：587（STARTTLS）</span></span>
<span class="line"><span>用户名：完整邮箱地址</span></span>
<span class="line"><span>密码：该邮箱的应用专用密码</span></span></code></pre></div><p>推荐 IMAP；POP3 更适合只下载单一收件箱的旧式客户端。不要在未加密连接中提交密码。</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};